"""Business logic and request validation for device registration/queries.

The service never sees plaintext messages or private keys: it validates and
stores identifiers and public-key material only.
"""
from __future__ import annotations

from typing import Any, Dict, List, Optional, Tuple

from .crypto import is_nonempty_string, load_public_key
from .models import Device, SignedPreKey
from .storage import (
    DELIVERY_BAD_SEQUENCE,
    DELIVERY_DEVICE_INACTIVE,
    DELIVERY_DEVICE_MISMATCH,
    DELIVERY_MESSAGE_UNKNOWN,
    DELIVERY_SESSION_UNKNOWN,
    MESSAGE_BAD_SEQUENCE,
    MESSAGE_DEVICE_INACTIVE,
    MESSAGE_DUPLICATE_ID,
    MESSAGE_SENDER_INACTIVE,
    MESSAGE_SESSION_UNKNOWN,
    SESSION_INITIATOR_REVOKED,
    SESSION_INITIATOR_UNKNOWN,
    SESSION_PREKEY_REVOKED,
    SESSION_PREKEY_UNKNOWN,
    SESSION_RECIPIENT_REVOKED,
    SESSION_RECIPIENT_UNKNOWN,
    DeviceStore,
    DeliveryError,
    MessageCreateError,
    MessageListError,
    SessionCreateError,
)

_REQUIRED_SCALAR_FIELDS = ("user_id", "device_id", "identity_key")
_SESSION_SCALAR_FIELDS = (
    "initiator_device_id", "recipient_device_id", "prekey_id", "ephemeral_key")
_MESSAGE_STRING_FIELDS = (
    "session_id", "sender_device_id", "message_id", "nonce", "ciphertext")

#: Maps a storage-level message-append failure reason to (HTTP status, field).
_MESSAGE_CREATE_ERROR_MAP = {
    MESSAGE_SESSION_UNKNOWN: (404, "session_id"),
    MESSAGE_SENDER_INACTIVE: (409, "sender_device_id"),
    MESSAGE_DUPLICATE_ID: (409, "message_id"),
    MESSAGE_BAD_SEQUENCE: (409, "sequence"),
}

#: Maps a storage-level session failure reason to (HTTP status, field name).
_SESSION_ERROR_MAP = {
    SESSION_INITIATOR_UNKNOWN: (404, "initiator_device_id"),
    SESSION_RECIPIENT_UNKNOWN: (404, "recipient_device_id"),
    SESSION_PREKEY_UNKNOWN: (404, "prekey_id"),
    SESSION_INITIATOR_REVOKED: (409, "initiator_device_id"),
    SESSION_RECIPIENT_REVOKED: (409, "recipient_device_id"),
    SESSION_PREKEY_REVOKED: (409, "prekey_id"),
}


class ServiceError(Exception):
    """A validation/lookup failure carrying an HTTP status and a field name."""

    def __init__(self, message: str, field: str = "", status_code: int = 400) -> None:
        super().__init__(message)
        self.message = message
        self.field = field
        self.status_code = status_code

    def to_body(self) -> Dict[str, Any]:
        """JSON-serializable error body naming the offending field."""
        body: Dict[str, Any] = {"message": self.message}
        if self.field:
            body["field"] = self.field
        return body


class DeviceService:
    """Validates payloads and coordinates the :class:`DeviceStore`."""

    def __init__(self, store: Optional[DeviceStore] = None) -> None:
        self.store = store if store is not None else DeviceStore()

    # -- registration ------------------------------------------------------

    def register(self, payload: object) -> Dict[str, Any]:
        """Validate and persist a registration payload; return the 201 body."""
        if not isinstance(payload, dict):
            raise ServiceError("request body must be a JSON object", "request_body")

        for name in _REQUIRED_SCALAR_FIELDS:
            if name not in payload:
                raise ServiceError(f"missing required field: {name}", name)
            if not is_nonempty_string(payload[name]):
                raise ServiceError(f"field must be a non-empty string: {name}", name)

        if "signed_prekeys" not in payload:
            raise ServiceError("missing required field: signed_prekeys",
                               "signed_prekeys")
        raw_prekeys = payload["signed_prekeys"]
        if not isinstance(raw_prekeys, list):
            raise ServiceError("field must be an array: signed_prekeys",
                               "signed_prekeys")

        prekeys: List[SignedPreKey] = []
        seen_key_ids: set = set()
        for index, element in enumerate(raw_prekeys):
            prefix = f"signed_prekeys[{index}]"
            if not isinstance(element, dict):
                raise ServiceError(f"array element must be an object: {prefix}", prefix)
            for subfield in ("key_id", "public_key"):
                path = f"{prefix}.{subfield}"
                if subfield not in element:
                    raise ServiceError(f"missing required field: {path}", path)
                if not is_nonempty_string(element[subfield]):
                    raise ServiceError(
                        f"field must be a non-empty string: {path}", path)
            if element["key_id"] in seen_key_ids:
                raise ServiceError(
                    f"duplicate key_id in signed_prekeys: {element['key_id']}",
                    f"{prefix}.key_id")
            if load_public_key(element["public_key"]) is None:
                raise ServiceError(
                    f"field is not a valid public key: {prefix}.public_key",
                    f"{prefix}.public_key")
            seen_key_ids.add(element["key_id"])
            prekeys.append(SignedPreKey(element["key_id"], element["public_key"]))

        if load_public_key(payload["identity_key"]) is None:
            raise ServiceError("field is not a valid public key: identity_key",
                               "identity_key")

        device = Device(
            user_id=payload["user_id"],
            device_id=payload["device_id"],
            identity_key=payload["identity_key"],
            prekeys=prekeys,
        )
        if not self.store.add_device(device):
            raise ServiceError(
                f"device_id already registered: {device.device_id}",
                "device_id", status_code=409)

        return {"device_id": device.device_id,
                "registered_at": device.registered_at}

    # -- lookup ------------------------------------------------------------

    def get_device(self, device_id: str) -> Dict[str, Any]:
        """Return the public device record; raise :class:`ServiceError` if absent."""
        view = self.store.public_view(device_id)
        if view is None:
            raise ServiceError(f"device not found: {device_id}",
                               "device_id", status_code=404)
        return view

    # -- revocation --------------------------------------------------------

    def revoke_device(self, device_id: str) -> Dict[str, Any]:
        """Revoke a device (and its pre-keys); idempotent, 404 when unknown."""
        device = self.store.revoke_device(device_id)
        if device is None:
            raise ServiceError(f"device not found: {device_id}",
                               "device_id", status_code=404)
        return {"device_id": device.device_id, "revoked": True}

    def revoke_prekey(self, device_id: str, key_id: str) -> Dict[str, Any]:
        """Revoke one pre-key; idempotent, 404 on unknown device/key."""
        device, key_found = self.store.revoke_prekey_by_id(device_id, key_id)
        if device is None:
            raise ServiceError(f"device not found: {device_id}",
                               "device_id", status_code=404)
        if not key_found:
            raise ServiceError(f"pre-key not found: {key_id}",
                               "key_id", status_code=404)
        return {"device_id": device.device_id, "key_id": key_id, "revoked": True}

    # -- sessions ----------------------------------------------------------

    def create_session(self, payload: object) -> Dict[str, Any]:
        """Validate a session-negotiation payload and atomically create it.

        Every request creates a fresh session (a new ``session_id``); repeated
        POSTs are never deduplicated.
        """
        if not isinstance(payload, dict):
            raise ServiceError("request body must be a JSON object",
                               "request_body")

        for name in _SESSION_SCALAR_FIELDS:
            if name not in payload:
                raise ServiceError(f"missing required field: {name}", name)
            if not is_nonempty_string(payload[name]):
                raise ServiceError(
                    f"field must be a non-empty string: {name}", name)

        if load_public_key(payload["ephemeral_key"]) is None:
            raise ServiceError(
                "field is not a valid public key: ephemeral_key",
                "ephemeral_key")

        if payload["initiator_device_id"] == payload["recipient_device_id"]:
            raise ServiceError(
                "recipient_device_id must differ from initiator_device_id",
                "recipient_device_id")

        try:
            session = self.store.create_session(
                payload["initiator_device_id"],
                payload["recipient_device_id"],
                payload["prekey_id"],
                payload["ephemeral_key"])
        except SessionCreateError as error:
            status_code, field = _SESSION_ERROR_MAP[error.reason]
            if status_code == 404:
                if field == "prekey_id":
                    message = f"pre-key not found: {payload['prekey_id']}"
                else:
                    device_id = payload[field]
                    message = f"device not found: {device_id}"
            else:
                message = f"{field} is revoked"
            raise ServiceError(message, field, status_code=status_code)

        return self.store.session_view(session.session_id)  # type: ignore[return-value]

    def get_session(self, session_id: str) -> Dict[str, Any]:
        """Return the immutable eight-field session snapshot; 404 if unknown."""
        view = self.store.session_view(session_id)
        if view is None:
            raise ServiceError(f"session not found: {session_id}",
                               "session_id", status_code=404)
        return view

    # -- messages ----------------------------------------------------------

    def post_message(self, payload: object) -> Dict[str, Any]:
        """Validate a message-send payload and atomically append the message.

        ``sequence`` must continue the session's stream (starting at 1, no
        gaps or duplicates) and ``message_id`` must be unique within the
        session; violations are 409s, as is a revoked/unknown sender device.
        """
        if not isinstance(payload, dict):
            raise ServiceError("request body must be a JSON object",
                               "request_body")

        for name in _MESSAGE_STRING_FIELDS:
            if name not in payload:
                raise ServiceError(f"missing required field: {name}", name)
            if not is_nonempty_string(payload[name]):
                raise ServiceError(
                    f"field must be a non-empty string: {name}", name)

        if "sequence" not in payload:
            raise ServiceError("missing required field: sequence", "sequence")
        sequence = payload["sequence"]
        # bool is a subclass of int; reject it explicitly.
        if not isinstance(sequence, int) or isinstance(sequence, bool):
            raise ServiceError("field must be an integer: sequence", "sequence")

        try:
            message = self.store.append_message(
                payload["session_id"],
                payload["sender_device_id"],
                payload["message_id"],
                sequence,
                payload["nonce"],
                payload["ciphertext"])
        except MessageCreateError as error:
            status_code, field = _MESSAGE_CREATE_ERROR_MAP[error.reason]
            if error.reason == MESSAGE_SESSION_UNKNOWN:
                message_text = f"session not found: {payload['session_id']}"
            elif error.reason == MESSAGE_SENDER_INACTIVE:
                message_text = "sender_device_id is not an active device"
            elif error.reason == MESSAGE_DUPLICATE_ID:
                message_text = (f"message_id already exists in session: "
                                f"{payload['message_id']}")
            else:
                message_text = (f"sequence must continue the session stream "
                                f"(got {sequence})")
            raise ServiceError(message_text, field, status_code=status_code)

        return self.store.message_view(message)

    def list_messages(self, session_id: str, device_id: str, after: int,
                      limit: int) -> Dict[str, Any]:
        """Return one page of a session's messages plus the resume cursor."""
        try:
            messages, next_after = self.store.message_page(
                session_id, device_id, after, limit)
        except MessageListError as error:
            if error.reason == MESSAGE_SESSION_UNKNOWN:
                raise ServiceError(f"session not found: {session_id}",
                                   "session_id", status_code=404)
            if error.reason == MESSAGE_DEVICE_INACTIVE:
                raise ServiceError("device_id is not an active device",
                                   "device_id", status_code=409)
            raise  # pragma: no cover - defensive
        return {"messages": messages, "next_after": next_after}

    # -- reliable delivery -------------------------------------------------

    #: Maps a delivery failure reason to (HTTP status, field name).
    _DELIVERY_ERROR_MAP = {
        DELIVERY_SESSION_UNKNOWN: (404, "session_id"),
        DELIVERY_MESSAGE_UNKNOWN: (404, "message_id"),
        DELIVERY_DEVICE_INACTIVE: (409, "device_id"),
        DELIVERY_DEVICE_MISMATCH: (409, "device_id"),
        DELIVERY_BAD_SEQUENCE: (409, "sequence"),
    }

    def _delivery_error(self, error: DeliveryError,
                        session_id: str, message_id: str,
                        sequence: Optional[int] = None) -> ServiceError:
        """Translate a storage :class:`DeliveryError` into a ServiceError."""
        status_code, field = self._DELIVERY_ERROR_MAP[error.reason]
        if error.reason == DELIVERY_SESSION_UNKNOWN:
            text = f"session not found: {session_id}"
        elif error.reason == DELIVERY_MESSAGE_UNKNOWN:
            text = f"message not found: {message_id}"
        elif error.reason == DELIVERY_BAD_SEQUENCE:
            text = f"sequence does not match the message (got {sequence})"
        else:
            text = "device_id is not the active recipient of this session"
        return ServiceError(text, field, status_code=status_code)

    def retry_message(self, session_id: str, message_id: str,
                      payload: object) -> Tuple[Dict[str, Any], int]:
        """Validate and record one delivery attempt for a message.

        Returns ``(body, 201)`` for the first attempt and ``(body, 200)`` for
        a repeated attempt. A repeated ``attempt_id`` is not counted again;
        retries after an ack still succeed with status ``acked``.
        """
        if not isinstance(payload, dict):
            raise ServiceError("request body must be a JSON object",
                               "request_body")
        for name in ("device_id", "attempt_id"):
            if name not in payload:
                raise ServiceError(f"missing required field: {name}", name)
            if not is_nonempty_string(payload[name]):
                raise ServiceError(
                    f"field must be a non-empty string: {name}", name)

        try:
            view, created = self.store.retry_message(
                session_id, message_id,
                payload["device_id"], payload["attempt_id"])
        except DeliveryError as error:
            raise self._delivery_error(error, session_id, message_id)
        return view, 201 if created else 200

    def ack_message(self, session_id: str, payload: object
                    ) -> Tuple[Dict[str, Any], int]:
        """Validate and record an acknowledgement.

        The session is taken from the URL; the body carries ``device_id``,
        ``message_id`` and the integer ``sequence``. The first ack returns 201
        and marks the message acked; repeated acks return 200 and leave the
        acked state in place.
        """
        if not isinstance(payload, dict):
            raise ServiceError("request body must be a JSON object",
                               "request_body")
        for name in ("device_id", "message_id"):
            if name not in payload:
                raise ServiceError(f"missing required field: {name}", name)
            if not is_nonempty_string(payload[name]):
                raise ServiceError(
                    f"field must be a non-empty string: {name}", name)
        if "sequence" not in payload:
            raise ServiceError("missing required field: sequence", "sequence")
        sequence = payload["sequence"]
        if not isinstance(sequence, int) or isinstance(sequence, bool):
            raise ServiceError("field must be an integer: sequence", "sequence")

        try:
            view, first_ack = self.store.ack_message(
                session_id, payload["message_id"],
                payload["device_id"], sequence)
        except DeliveryError as error:
            raise self._delivery_error(
                error, session_id, payload["message_id"], sequence)
        return view, 201 if first_ack else 200

    def message_status(self, session_id: str, message_id: str,
                       device_id: str) -> Dict[str, Any]:
        """Return one message's delivery status for its active recipient."""
        try:
            return self.store.message_delivery_status(
                session_id, message_id, device_id)
        except DeliveryError as error:
            raise self._delivery_error(error, session_id, message_id)

"""HTTP layer: JSON API over the standard library's ``http.server``."""
from __future__ import annotations

import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any, Dict, Optional, Tuple
from urllib.parse import parse_qs, unquote, urlsplit

from .service import DeviceService, ServiceError

_DEVICES_PATH = "/v1/devices"
_SESSIONS_PATH = "/v1/sessions"
_MESSAGES_PATH = "/v1/messages"

#: Sentinel meaning a 400 for a malformed body was already sent.
_BAD_REQUEST = object()


class DeviceHTTPHandler(BaseHTTPRequestHandler):
    """Routes for ``POST /v1/devices`` and ``GET /v1/devices/{device_id}``."""

    service: DeviceService  # injected via :func:`handler_for`

    # -- routing ----------------------------------------------------------

    def do_POST(self) -> None:
        path = urlsplit(self.path).path
        if path == _DEVICES_PATH:
            self._handle_register()
        elif path == _SESSIONS_PATH:
            self._handle_create_session()
        elif path == _MESSAGES_PATH:
            self._handle_post_message()
        elif path.startswith(_DEVICES_PATH + "/") and path.endswith("/revoke"):
            self._route_revoke(path)
        elif path.startswith(_MESSAGES_PATH + "/") and path.endswith("/acks"):
            self._route_acks(path)
        elif path.startswith(_MESSAGES_PATH + "/") and "/retry/" in path:
            self._route_retry(path)
        else:
            self._send_json(404, {"message": f"not found: {path}"})

    def _route_retry(self, path: str) -> None:
        suffix = path[len(_MESSAGES_PATH) + 1:]
        parts = suffix.split("/")
        if len(parts) == 3 and parts[1] == "retry" and parts[0] and parts[2]:
            self._handle_retry_message(unquote(parts[0]), unquote(parts[2]))
        else:
            self._send_json(404, {"message": "session not found",
                                  "field": "session_id"})

    def _route_acks(self, path: str) -> None:
        suffix = path[len(_MESSAGES_PATH) + 1:-len("/acks")]
        parts = suffix.split("/")
        if len(parts) == 1 and parts[0]:
            self._handle_ack_message(unquote(parts[0]))
        else:
            self._send_json(404, {"message": "session not found",
                                  "field": "session_id"})

    def _route_revoke(self, path: str) -> None:
        # Split on raw slashes only; a percent-encoded slash inside a segment
        # is part of the id, mirroring the GET route.
        suffix = path[len(_DEVICES_PATH) + 1:-len("/revoke")]
        parts = suffix.split("/")
        if len(parts) == 1:
            self._handle_revoke_device(unquote(parts[0]))
        elif len(parts) == 3 and parts[1] == "prekeys":
            self._handle_revoke_prekey(unquote(parts[0]), unquote(parts[2]))
        else:
            self._send_json(404, {"message": "device not found",
                                  "field": "device_id"})

    def do_GET(self) -> None:
        path = urlsplit(self.path).path
        if path.startswith(_DEVICES_PATH + "/"):
            suffix = path[len(_DEVICES_PATH) + 1:]
            # A real slash means a sub-path (…/devices/a/b); a percent-encoded
            # slash within a single segment is part of the device id.
            if not suffix or "/" in suffix:
                self._send_json(404, {"message": "device not found",
                                      "field": "device_id"})
                return
            self._handle_show(unquote(suffix))
        elif path.startswith(_SESSIONS_PATH + "/"):
            suffix = path[len(_SESSIONS_PATH) + 1:]
            if not suffix or "/" in suffix:
                self._send_json(404, {"message": "session not found",
                                      "field": "session_id"})
                return
            self._handle_show_session(unquote(suffix))
        elif path.startswith(_MESSAGES_PATH + "/"):
            suffix = path[len(_MESSAGES_PATH) + 1:]
            if "/" in suffix:
                parts = suffix.split("/")
                if len(parts) == 3 and parts[1] == "status" and parts[0] and parts[2]:
                    self._handle_message_status(
                        unquote(parts[0]), unquote(parts[2]))
                else:
                    self._send_json(404, {"message": "session not found",
                                          "field": "session_id"})
                return
            if not suffix:
                self._send_json(404, {"message": "session not found",
                                      "field": "session_id"})
                return
            self._handle_list_messages(unquote(suffix))
        else:
            self._send_json(404, {"message": f"not found: {path}"})

    # -- handlers ---------------------------------------------------------

    def _handle_register(self) -> None:
        payload = self._read_json_request()
        if payload is _BAD_REQUEST:
            return
        try:
            body = self.service.register(payload)
        except ServiceError as error:
            self._send_json(error.status_code, error.to_body())
            return
        self._send_json(201, body)

    def _handle_show(self, device_id: str) -> None:
        try:
            body = self.service.get_device(device_id)
        except ServiceError as error:
            self._send_json(error.status_code, error.to_body())
            return
        self._send_json(200, body)

    def _handle_revoke_device(self, device_id: str) -> None:
        try:
            body = self.service.revoke_device(device_id)
        except ServiceError as error:
            self._send_json(error.status_code, error.to_body())
            return
        self._send_json(200, body)

    def _handle_revoke_prekey(self, device_id: str, key_id: str) -> None:
        try:
            body = self.service.revoke_prekey(device_id, key_id)
        except ServiceError as error:
            self._send_json(error.status_code, error.to_body())
            return
        self._send_json(200, body)

    def _handle_create_session(self) -> None:
        payload = self._read_json_request()
        if payload is _BAD_REQUEST:
            return
        try:
            body = self.service.create_session(payload)
        except ServiceError as error:
            self._send_json(error.status_code, error.to_body())
            return
        self._send_json(201, body)

    def _handle_show_session(self, session_id: str) -> None:
        try:
            body = self.service.get_session(session_id)
        except ServiceError as error:
            self._send_json(error.status_code, error.to_body())
            return
        self._send_json(200, body)

    def _handle_post_message(self) -> None:
        payload = self._read_json_request()
        if payload is _BAD_REQUEST:
            return
        try:
            body = self.service.post_message(payload)
        except ServiceError as error:
            self._send_json(error.status_code, error.to_body())
            return
        self._send_json(201, body)

    def _handle_list_messages(self, session_id: str) -> None:
        params = self._message_query_params()
        if params is None:
            return  # a 400 response was already sent
        device_id, after, limit = params
        try:
            body = self.service.list_messages(session_id, device_id,
                                              after, limit)
        except ServiceError as error:
            self._send_json(error.status_code, error.to_body())
            return
        self._send_json(200, body)

    def _handle_retry_message(self, session_id: str, message_id: str) -> None:
        payload = self._read_json_request()
        if payload is _BAD_REQUEST:
            return
        try:
            body, status_code = self.service.retry_message(
                session_id, message_id, payload)
        except ServiceError as error:
            self._send_json(error.status_code, error.to_body())
            return
        self._send_json(status_code, body)

    def _handle_ack_message(self, session_id: str) -> None:
        payload = self._read_json_request()
        if payload is _BAD_REQUEST:
            return
        try:
            body, status_code = self.service.ack_message(session_id, payload)
        except ServiceError as error:
            self._send_json(error.status_code, error.to_body())
            return
        self._send_json(status_code, body)

    def _handle_message_status(self, session_id: str, message_id: str) -> None:
        device_id = self._required_device_param()
        if device_id is None:
            return  # a 400 response was already sent
        try:
            body = self.service.message_status(
                session_id, message_id, device_id)
        except ServiceError as error:
            self._send_json(error.status_code, error.to_body())
            return
        self._send_json(200, body)

    def _required_device_param(self) -> Optional[str]:
        """Validate the single required ``device_id`` query parameter.

        Returns the value, or ``None`` after sending 400 when it is missing,
        empty, or supplied more than once.
        """
        query = parse_qs(urlsplit(self.path).query)
        values = query.get("device_id", [])
        if len(values) != 1 or not values[0]:
            self._send_json(400, {"message": "device_id is required",
                                  "field": "device_id"})
            return None
        return values[0]

    def _message_query_params(self) -> Optional[Tuple[str, int, int]]:
        """Validate ``device_id``/``after``/``limit`` query parameters.

        Returns ``(device_id, after, limit)``, or ``None`` after sending the
        400 response itself when a parameter is missing or malformed.
        """
        query = parse_qs(urlsplit(self.path).query)

        device_ids = query.get("device_id", [])
        if len(device_ids) != 1 or not device_ids[0]:
            self._send_json(400, {"message": "device_id is required",
                                  "field": "device_id"})
            return None

        after = self._int_param(query, "after", default=0, minimum=0)
        if after is None:
            return None
        limit = self._int_param(query, "limit", default=100,
                                minimum=1, maximum=100)
        if limit is None:
            return None
        return device_ids[0], after, limit

    def _int_param(self, query: Dict[str, list], name: str, default: int,
                   minimum: int, maximum: Optional[int] = None
                   ) -> Optional[int]:
        """Parse one integer query parameter; send a 400 and return ``None``
        when it is missing its single value, malformed, or out of range."""
        values = query.get(name)
        if not values:
            return default
        if len(values) != 1:
            self._send_json(400, {"message": f"{name} must appear at most once",
                                  "field": name})
            return None
        try:
            value = int(values[0])
        except ValueError:
            self._send_json(400, {"message": f"{name} must be an integer",
                                  "field": name})
            return None
        if value < minimum or (maximum is not None and value > maximum):
            self._send_json(400, {"message": f"{name} is out of range",
                                  "field": name})
            return None
        return value

    # -- plumbing ---------------------------------------------------------

    def _read_json_request(self) -> Any:
        """Read and decode a JSON request body.

        Returns the decoded value, or the :data:`_BAD_REQUEST` sentinel after
        sending the 400 response itself when the body cannot be read.
        """
        try:
            length = int(self.headers.get("Content-Length", "0"))
        except ValueError:
            self._send_json(400, {"message": "invalid Content-Length header",
                                  "field": "Content-Length"})
            return _BAD_REQUEST
        raw = self.rfile.read(length) if length > 0 else b""
        try:
            return json.loads(raw.decode("utf-8")) if raw else None
        except (UnicodeDecodeError, json.JSONDecodeError):
            self._send_json(400, {"message": "request body must be valid JSON",
                                  "field": "request_body"})
            return _BAD_REQUEST

    def _send_json(self, status_code: int, body: Any) -> None:
        data = json.dumps(body, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def log_message(self, format: str, *args: Any) -> None:
        """Keep the server quiet; tests and CLIs speak JSON."""
        return


def handler_for(service: DeviceService) -> type:
    """Return a handler class bound to *service*."""

    class _BoundHandler(DeviceHTTPHandler):
        pass

    _BoundHandler.service = service
    return _BoundHandler


def create_server(host: str, port: int,
                  service: Optional[DeviceService] = None) -> Tuple[ThreadingHTTPServer, DeviceService]:
    """Build (but do not start) the HTTP server; return it with its service."""
    if service is None:
        service = DeviceService()
    server = ThreadingHTTPServer((host, port), handler_for(service))
    return server, service

"""Public-key parsing and validation helpers built on the ``cryptography`` library.

The server only ever sees *public* key material. These helpers accept the common
wire encodings clients use to publish identity keys and signed pre-keys:

* PEM text (SubjectPublicKeyInfo),
* base64- or hex-encoded DER (SubjectPublicKeyInfo),
* raw 32-byte X25519/Ed25519 points (base64- or hex-encoded).
"""
from __future__ import annotations

import base64
import binascii
import os

from cryptography.exceptions import InvalidTag, UnsupportedAlgorithm
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import ed25519, x25519
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from typing import Optional

#: AES-GCM nonce size in bytes (96-bit nonces, as recommended for GCM).
GCM_NONCE_BYTES = 12
#: AES-GCM authentication tag size in bytes (appended to the ciphertext).
GCM_TAG_BYTES = 16
#: AES-256 key size in bytes.
AES_KEY_BYTES = 32


class CryptoError(Exception):
    """A local encryption/decryption failure naming the offending field."""

    def __init__(self, message: str, field: str) -> None:
        super().__init__(message)
        self.message = message
        self.field = field


def _decode_strict_base64(value: str, field: str) -> bytes:
    """Decode standard base64; raise :class:`CryptoError` on failure."""
    try:
        return base64.b64decode(value, validate=True)
    except (binascii.Error, ValueError):
        raise CryptoError(f"field must be valid base64: {field}", field) from None


def _load_aes_key(key_b64: str) -> AESGCM:
    """Decode a base64 AES-256 key (exactly 32 bytes) into an AES-GCM cipher."""
    if not is_nonempty_string(key_b64):
        raise CryptoError("field must be a non-empty string: key", "key")
    key = _decode_strict_base64(key_b64, "key")
    if len(key) != AES_KEY_BYTES:
        raise CryptoError(
            f"key must decode to {AES_KEY_BYTES} bytes (got {len(key)})", "key")
    return AESGCM(key)


def encrypt_message(session_id: str, key_b64: str,
                    plaintext: str) -> dict:
    """Encrypt *plaintext* (UTF-8) with AES-256-GCM.

    The 12-byte nonce is generated randomly; the session id is bound to the
    ciphertext as additional authenticated data. Returns a dict with
    ``session_id``, ``nonce`` and ``ciphertext`` (both base64; the ciphertext
    carries the 16-byte GCM tag appended).
    """
    if not is_nonempty_string(session_id):
        raise CryptoError("field must be a non-empty string: session_id",
                          "session_id")
    if not isinstance(plaintext, str):
        raise CryptoError("field must be a string: plaintext", "plaintext")
    cipher = _load_aes_key(key_b64)
    nonce = os.urandom(GCM_NONCE_BYTES)
    ciphertext = cipher.encrypt(nonce, plaintext.encode("utf-8"),
                                session_id.encode("utf-8"))
    return {
        "session_id": session_id,
        "nonce": base64.b64encode(nonce).decode("ascii"),
        "ciphertext": base64.b64encode(ciphertext).decode("ascii"),
    }


def decrypt_message(session_id: str, key_b64: str, nonce_b64: str,
                    ciphertext_b64: str) -> dict:
    """Decrypt a payload produced by :func:`encrypt_message`.

    Returns a dict with ``session_id`` and the UTF-8 ``plaintext``. Any
    decoding or authentication failure raises :class:`CryptoError` naming the
    offending field.
    """
    if not is_nonempty_string(session_id):
        raise CryptoError("field must be a non-empty string: session_id",
                          "session_id")
    cipher = _load_aes_key(key_b64)

    if not is_nonempty_string(nonce_b64):
        raise CryptoError("field must be a non-empty string: nonce", "nonce")
    nonce = _decode_strict_base64(nonce_b64, "nonce")
    if len(nonce) != GCM_NONCE_BYTES:
        raise CryptoError(
            f"nonce must decode to {GCM_NONCE_BYTES} bytes (got {len(nonce)})",
            "nonce")

    if not is_nonempty_string(ciphertext_b64):
        raise CryptoError("field must be a non-empty string: ciphertext",
                          "ciphertext")
    ciphertext = _decode_strict_base64(ciphertext_b64, "ciphertext")
    if len(ciphertext) < GCM_TAG_BYTES:
        raise CryptoError("ciphertext is too short to carry a GCM tag",
                          "ciphertext")

    try:
        plaintext = cipher.decrypt(nonce, ciphertext,
                                   session_id.encode("utf-8"))
    except InvalidTag:
        raise CryptoError("ciphertext failed authentication", "ciphertext") \
            from None
    try:
        text = plaintext.decode("utf-8")
    except UnicodeDecodeError:
        raise CryptoError("plaintext is not valid UTF-8", "plaintext") \
            from None
    return {"session_id": session_id, "plaintext": text}


def is_nonempty_string(value: object) -> bool:
    """Return True iff *value* is a ``str`` that contains at least one character."""
    return isinstance(value, str) and len(value) > 0


def _decode_base64(value: str) -> Optional[bytes]:
    """Decode standard base64 (padding optional); return ``None`` on failure."""
    try:
        padded = value + "=" * (-len(value) % 4)
        return base64.b64decode(padded, validate=True)
    except (binascii.Error, ValueError):
        return None


def _decode_hex(value: str) -> Optional[bytes]:
    """Decode a hex string; return ``None`` on failure."""
    try:
        return binascii.unhexlify(value)
    except (binascii.Error, ValueError):
        return None


def _load_raw_point(data: bytes) -> Optional[object]:
    """Parse a raw 32-byte X25519 or Ed25519 public point."""
    if len(data) != 32:
        return None
    for loader in (x25519.X25519PublicKey.from_public_bytes,
                   ed25519.Ed25519PublicKey.from_public_bytes):
        try:
            return loader(data)
        except (ValueError, UnsupportedAlgorithm):
            continue
    return None


def _load_der(data: bytes) -> Optional[object]:
    try:
        return serialization.load_der_public_key(data)
    except (ValueError, UnsupportedAlgorithm, TypeError):
        return None


def load_public_key(value: str) -> Optional[object]:
    """Best-effort parse of a public key.

    Returns the parsed key object, or ``None`` when it cannot be parsed. Only
    public material is ever handled here; private keys are not loaded on purpose.
    """
    if not is_nonempty_string(value):
        return None

    # 1) PEM text.
    try:
        return serialization.load_pem_public_key(value.encode("ascii"))
    except (ValueError, UnsupportedAlgorithm, TypeError):
        pass

    # 2) Encoded bytes: collect every plausible decoding. A hex string can also
    #    be valid base64 (e.g. a 64-char hex digest), so both are candidates and
    #    the first one that actually parses as a key wins.
    candidates: list[bytes] = []
    blob = _decode_base64(value)
    if blob is not None:
        candidates.append(blob)
    blob = _decode_hex(value)
    if blob is not None and blob not in candidates:
        candidates.append(blob)

    # 3) Raw 32-byte point (X25519/Ed25519), otherwise DER SubjectPublicKeyInfo.
    for candidate in candidates:
        raw = _load_raw_point(candidate)
        if raw is not None:
            return raw
        der = _load_der(candidate)
        if der is not None:
            return der
    return None

